// Per-customer cap on proactive agent messages: at most LIMIT in any rolling
// 24-hour window, counted across sms, push and chat together.
//
// State lives in STATE_DIR so that separate worker processes share it:
//   users/<sha256(userId)>.json  { "sent": [{ "at": <ms>, "channel": "sms" }, ...] }
//   locks/<sha256(userId)>.lock  a directory; mkdir is atomic, so it serves as a mutex
// Each reserve() call takes the customer's lock, reads the list, decides, and
// writes the list back before releasing the lock. Other customers use other
// locks, so they never wait on each other.

import { createHash, randomBytes } from 'node:crypto';
import { mkdir, open, readFile, rename, rmdir, stat, writeFile } from 'node:fs/promises';
import path from 'node:path';

const LIMIT = 5;
const WINDOW_MS = 24 * 60 * 60 * 1000;
// Entries older than the window are dropped only after an extra hour, so a
// caller whose clock runs slightly behind another caller still sees every entry it needs.
const PRUNE_KEEP_MS = WINDOW_MS + 60 * 60 * 1000;
const CHANNELS = new Set(['sms', 'push', 'chat']);
// A lock older than this is assumed to belong to a crashed process. The critical
// section only does a few small file operations, so this is far longer than needed.
const LOCK_STALE_MS = 10_000;
const LOCK_WAIT_MS = 10_000;

export async function reserve(userId, channel, now) {
  if (typeof userId !== 'string' || userId === '') {
    throw new TypeError('userId must be a non-empty string');
  }
  if (!CHANNELS.has(channel)) {
    throw new TypeError(`channel must be one of sms, push, chat (got ${String(channel)})`);
  }
  if (!(now instanceof Date) || Number.isNaN(now.getTime())) {
    throw new TypeError('now must be a valid Date');
  }

  const stateDir = process.env.STATE_DIR;
  if (!stateDir) {
    throw new Error('STATE_DIR environment variable is not set');
  }

  const usersDir = path.join(stateDir, 'users');
  const locksDir = path.join(stateDir, 'locks');
  await mkdir(usersDir, { recursive: true });
  await mkdir(locksDir, { recursive: true });

  const key = createHash('sha256').update(userId, 'utf8').digest('hex');
  const file = path.join(usersDir, `${key}.json`);
  const nowMs = now.getTime();

  return withLock(path.join(locksDir, `${key}.lock`), async () => {
    const stored = await loadSent(file);
    const kept = stored.filter((e) => e.at > nowMs - PRUNE_KEEP_MS);
    const inWindow = kept
      .filter((e) => e.at > nowMs - WINDOW_MS)
      .map((e) => e.at)
      .sort((a, b) => a - b);

    if (inWindow.length < LIMIT) {
      kept.push({ at: nowMs, channel });
      await saveSent(file, kept);
      return {
        allowed: true,
        retryAt: null,
        reason: `Allowed: ${inWindow.length + 1} of ${LIMIT} proactive messages used in the last 24 hours.`,
      };
    }

    // The window must hold at most LIMIT - 1 entries before a new one is added.
    // Entry number inWindow.length - LIMIT (0-based) is the last one that has to age out.
    // Its 24-hour mark is the earliest moment the count drops enough.
    const retryMs = inWindow[inWindow.length - LIMIT] + WINDOW_MS;
    const retryAt = new Date(retryMs);
    return {
      allowed: false,
      retryAt,
      reason:
        `Not sent: this customer already received ${LIMIT} proactive agent messages in the last 24 hours ` +
        `(limit is ${LIMIT} per 24 hours across all channels combined). ` +
        `The next one can go after ${retryAt.toISOString()}.`,
    };
  });
}

async function withLock(lockPath, fn) {
  const deadline = Date.now() + LOCK_WAIT_MS;
  for (;;) {
    try {
      await mkdir(lockPath);
      break;
    } catch (err) {
      if (err.code !== 'EEXIST') throw err;
    }
    await breakIfStale(lockPath);
    if (Date.now() > deadline) {
      throw new Error(`timed out waiting for lock ${path.basename(lockPath)}`);
    }
    await sleep(5 + Math.random() * 15);
  }
  try {
    return await fn();
  } finally {
    await rmdir(lockPath).catch((err) => {
      if (err.code !== 'ENOENT') throw err;
    });
  }
}

async function breakIfStale(lockPath) {
  let info;
  try {
    info = await stat(lockPath);
  } catch (err) {
    if (err.code === 'ENOENT') return;
    throw err;
  }
  if (Date.now() - info.mtimeMs < LOCK_STALE_MS) return;
  // Renaming first means only one process can remove this particular lock.
  const graveyard = `${lockPath}.stale-${randomBytes(6).toString('hex')}`;
  try {
    await rename(lockPath, graveyard);
    await rmdir(graveyard);
  } catch (err) {
    if (err.code !== 'ENOENT') throw err;
  }
}

async function loadSent(file) {
  let raw;
  try {
    raw = await readFile(file, 'utf8');
  } catch (err) {
    if (err.code === 'ENOENT') return [];
    throw err;
  }
  // A corrupt file throws here, so reserve() rejects and nothing is sent.
  const data = JSON.parse(raw);
  if (!data || !Array.isArray(data.sent)) {
    throw new Error(`corrupt state file: ${file}`);
  }
  return data.sent;
}

async function saveSent(file, sent) {
  // Write to a temp file, fsync it, then rename, so a crash never leaves a half-written state file.
  const tmp = `${file}.${process.pid}.${randomBytes(4).toString('hex')}.tmp`;
  const handle = await open(tmp, 'w');
  try {
    await handle.writeFile(JSON.stringify({ sent }));
    await handle.sync();
  } finally {
    await handle.close();
  }
  await rename(tmp, file);
}

function sleep(ms) {
  return new Promise((resolve) => setTimeout(resolve, ms));
}

import { test } from 'node:test';
import assert from 'node:assert/strict';
import { spawn } from 'node:child_process';
import { mkdtemp, rm } from 'node:fs/promises';
import { tmpdir } from 'node:os';
import path from 'node:path';
import { pathToFileURL } from 'node:url';
import { reserve } from './bot.mjs';

const DAY = 24 * 60 * 60 * 1000;
const MODULE_URL = pathToFileURL(path.resolve('bot.mjs')).href;

async function withStateDir(fn) {
  const base = await mkdtemp(path.join(tmpdir(), 'bot-test-'));
  // Nested, not yet existing: reserve() must create the missing parents.
  const stateDir = path.join(base, 'a', 'b', 'state');
  const previous = process.env.STATE_DIR;
  process.env.STATE_DIR = stateDir;
  try {
    await fn(stateDir);
  } finally {
    process.env.STATE_DIR = previous;
    await rm(base, { recursive: true, force: true });
  }
}

test('allows 5 sends, blocks the 6th, retryAt is oldest send + 24h', async () => {
  await withStateDir(async () => {
    const t0 = new Date('2026-10-01T10:00:00Z');
    for (let i = 0; i < 5; i++) {
      const r = await reserve('cust-1', 'sms', new Date(t0.getTime() + i * 1000));
      assert.equal(r.allowed, true);
      assert.equal(r.retryAt, null);
      assert.equal(typeof r.reason, 'string');
    }
    const blocked = await reserve('cust-1', 'push', new Date(t0.getTime() + 10_000));
    assert.equal(blocked.allowed, false);
    assert.equal(blocked.retryAt.getTime(), t0.getTime() + DAY);
    assert.match(blocked.reason, /5 proactive/);
    assert.match(blocked.reason, /all channels/);
  });
});

test('blocked calls are not counted', async () => {
  await withStateDir(async () => {
    const t0 = new Date('2026-10-01T10:00:00Z');
    for (let i = 0; i < 5; i++) await reserve('cust-2', 'chat', t0);
    for (let i = 0; i < 20; i++) {
      const r = await reserve('cust-2', 'chat', new Date(t0.getTime() + 1000 * i));
      assert.equal(r.allowed, false);
    }
    // Once the first send ages out, exactly one new send fits, because the blocked calls were not stored.
    const edge = new Date(t0.getTime() + DAY);
    assert.equal((await reserve('cust-2', 'chat', edge)).allowed, true);
    assert.equal((await reserve('cust-2', 'chat', edge)).allowed, true, 'the 5 sends at t0 are not all out yet');
  });
});

test('retryAt is exact: blocked 1 ms before, allowed at retryAt', async () => {
  await withStateDir(async () => {
    const t0 = new Date('2026-10-01T10:00:00.000Z');
    const times = [0, 100, 200, 300, 400].map((d) => new Date(t0.getTime() + d));
    for (const t of times) assert.equal((await reserve('cust-3', 'sms', t)).allowed, true);
    const probe = new Date(t0.getTime() + 500);
    const blocked = await reserve('cust-3', 'sms', probe);
    assert.equal(blocked.allowed, false);
    const retry = blocked.retryAt;
    assert.equal(retry.getTime(), t0.getTime() + DAY);

    const justBefore = new Date(retry.getTime() - 1);
    assert.equal((await reserve('cust-3', 'sms', justBefore)).allowed, false);
    const atRetry = await reserve('cust-3', 'sms', retry);
    assert.equal(atRetry.allowed, true);
  });
});

test('limit counts all channels together', async () => {
  await withStateDir(async () => {
    const t0 = new Date('2026-10-01T10:00:00Z');
    const channels = ['sms', 'push', 'chat', 'sms', 'push'];
    for (const [i, ch] of channels.entries()) {
      assert.equal((await reserve('cust-4', ch, new Date(t0.getTime() + i))).allowed, true);
    }
    assert.equal((await reserve('cust-4', 'chat', new Date(t0.getTime() + 9))).allowed, false);
  });
});

test('sliding window: sends spread over more than 24h are allowed as they age out', async () => {
  await withStateDir(async () => {
    const t0 = new Date('2026-10-01T00:00:00Z');
    // One send every 6 hours: 5 sends in the first 24h window, then the 6th at 24h.
    for (let i = 0; i < 5; i++) {
      assert.equal((await reserve('cust-5', 'push', new Date(t0.getTime() + i * 6 * 3600_000))).allowed, true);
    }
    const sixth = new Date(t0.getTime() + 4 * 6 * 3600_000 + 1000); // 24h after the 1st send, 1s later
    const r = await reserve('cust-5', 'push', new Date(t0.getTime() + 24 * 3600_000 + 1000));
    assert.equal(r.allowed, true, 'at 24h+1s the first send has aged out');
    assert.ok(sixth);
    const denied = await reserve('cust-5', 'push', new Date(t0.getTime() + 24 * 3600_000 + 2000));
    assert.equal(denied.allowed, false, 'window now holds sends at 6h,12h,18h,24h');
    // Entries at 6h,12h,18h,24h: 5th oldest is 6h... the earliest allowed time is 6h + 24h.
    assert.equal(denied.retryAt.getTime(), t0.getTime() + 6 * 3600_000 + DAY);
  });
});

test('different customers do not affect each other', async () => {
  await withStateDir(async () => {
    const t0 = new Date('2026-10-01T10:00:00Z');
    for (let i = 0; i < 5; i++) await reserve('cust-A', 'sms', t0);
    assert.equal((await reserve('cust-A', 'sms', t0)).allowed, false);
    assert.equal((await reserve('cust-B', 'sms', t0)).allowed, true);
    assert.equal((await reserve('cust-B/../../x', 'sms', t0)).allowed, true, 'odd ids are hashed, not used as paths');
  });
});

test('state survives a restart (fresh process sees earlier sends)', async () => {
  await withStateDir(async (stateDir) => {
    const t0 = new Date('2026-10-01T10:00:00Z');
    for (let i = 0; i < 5; i++) await reserve('cust-R', 'chat', t0);
    const out = await runChild(
      `const r = await reserve('cust-R', 'chat', new Date('${t0.toISOString()}'));
       console.log(JSON.stringify({ allowed: r.allowed }));`,
      stateDir,
    );
    assert.equal(JSON.parse(out).allowed, false);
  });
});

test('concurrent processes never exceed the limit', async () => {
  await withStateDir(async (stateDir) => {
    const t0 = new Date('2026-10-01T10:00:00Z').toISOString();
    const script = `
      const results = [];
      for (let i = 0; i < 4; i++) {
        results.push((await reserve('cust-C', 'sms', new Date('${t0}'))).allowed);
      }
      console.log(JSON.stringify(results));`;
    const outs = await Promise.all(Array.from({ length: 10 }, () => runChild(script, stateDir)));
    const allowed = outs.flatMap((o) => JSON.parse(o)).filter(Boolean).length;
    assert.equal(allowed, 5, `expected exactly 5 allowed across 40 attempts, got ${allowed}`);
  });
});

test('invalid input throws TypeError', async () => {
  await withStateDir(async () => {
    const d = new Date();
    await assert.rejects(reserve('', 'sms', d), TypeError);
    await assert.rejects(reserve(42, 'sms', d), TypeError);
    await assert.rejects(reserve('c', 'email', d), TypeError);
    await assert.rejects(reserve('c', 'sms', Date.now()), TypeError);
    await assert.rejects(reserve('c', 'sms', new Date('nope')), TypeError);
  });
});

test('corrupt state file rejects instead of allowing a send', async () => {
  await withStateDir(async (stateDir) => {
    const t0 = new Date('2026-10-01T10:00:00Z');
    await reserve('cust-X', 'sms', t0);
    const { createHash } = await import('node:crypto');
    const key = createHash('sha256').update('cust-X', 'utf8').digest('hex');
    const { writeFile } = await import('node:fs/promises');
    await writeFile(path.join(stateDir, 'users', `${key}.json`), '{not json');
    await assert.rejects(reserve('cust-X', 'sms', t0));
  });
});

function runChild(body, stateDir) {
  const code = `import { reserve } from ${JSON.stringify(MODULE_URL)};\n${body}`;
  return new Promise((resolve, reject) => {
    const child = spawn(process.execPath, ['--input-type=module', '-e', code], {
      env: { ...process.env, STATE_DIR: stateDir },
    });
    let out = '';
    let err = '';
    child.stdout.on('data', (d) => (out += d));
    child.stderr.on('data', (d) => (err += d));
    child.on('error', reject);
    child.on('close', (status) => {
      if (status !== 0) reject(new Error(`child failed: ${err}`));
      else resolve(out.trim());
    });
  });
}

